from vtkmodules.vtkIOXML import vtkXMLImageDataReader
from vtkmodules.util.numpy_support import vtk_to_numpy
import numpy as np
r=vtkXMLImageDataReader();r.SetFileName('/workspace/Ocean.vti');r.Update();d=r.GetOutput().GetPointData(); A,B,C,D=[vtk_to_numpy(d.GetArray(n)).reshape(101,101) for n in 'ABCD']; P=A-D;Q=B+C
# piecewise linear triangles (not bilinear) all edge zero contours via triangle affine solve
pts=[]
for y in range(100):
 for x in range(100):
  for tri in [(0,1,3),(0,3,2)]:
   corners=np.array([[0,0],[1,0],[0,1],[1,1]],float); vals=np.array([[P[y,x],Q[y,x]],[P[y,x+1],Q[y,x+1]],[P[y+1,x],Q[y+1,x]],[P[y+1,x+1],Q[y+1,x+1]]])
   c=corners[list(tri)]; v=vals[list(tri)]
   M=np.c_[c,np.ones(3)]
   coef=np.linalg.solve(M,v)
   xy=np.linalg.solve(coef[:2].T,-coef[2])
   if min(xy)>=-1e-10 and max(xy)<=1+1e-10: pts.append((x+xy[0],y+xy[1]))
print(len(pts),pts[:10])
